// Internal sandbox prebook guard. Preserves the approved sale price; does not create a payment or booking.
function "supplier/checkout/prepare" {
  input {
    int deal_id
    text checkin filters=trim
    text checkout filters=trim
    int guests
  }

  stack {
    db.get deals {
      field_name = "id"
      field_value = $input.deal_id
    } as $before_deal

    db.query supplier_deals {
      where = $db.supplier_deals.deal_id == $input.deal_id
      return = {type: "single"}
    } as $before_supplier

    function.run "supplier/availability/check" {
      input = {
        deal_id : $input.deal_id
        checkin : $input.checkin
        checkout: $input.checkout
        guests  : $input.guests
      }
    } as $availability

    precondition ($availability.available && $availability.environment == "sandbox") {
      error_type = "inputerror"
      error = "No approved, margin-safe sandbox offer is available"
    }

    function.run "connector/adapters/nuitee/prebook" {
      input = {offer_id: $availability.offer_id}
    } as $prebook

    db.get deals {
      field_name = "id"
      field_value = $input.deal_id
    } as $deal

    db.query supplier_deals {
      where = $db.supplier_deals.deal_id == $input.deal_id
      return = {type: "single"}
    } as $supplier

    api.lambda {
      code = """
        const a=$var.availability, p=$var.prebook, d=$var.deal, s=$var.supplier;
        const fail=(code,message)=>({ready:false,can_pay:false,environment:'sandbox',code,message});
        const canonical=v=>JSON.stringify(v,(_k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);
        if(!d||!s||d.status!=='active'||!d.approved_at||d.deleted_at||s.provider!=='nuitee'||s.environment!=='sandbox')return fail('NOT_APPROVED','Deal is niet meer goedgekeurd.');
        if(canonical(d)!==canonical($var.before_deal)||canonical(s)!==canonical($var.before_supplier)||Number(d.price)!==a.customer_price)return fail('DEAL_CHANGED','Deal is gewijzigd tijdens de controle.');
        if(Date.now()>a.valid_until)return fail('EXPIRED','Beschikbaarheidscontrole is verlopen.');
        if(!p?.success||!p.data?.prebookId)return fail('PREBOOK_FAILED','Nuitee heeft de prijs niet bevestigd.');
        const q=p.data;
        if(q.currency!=='EUR'||typeof q.price!=='number'||!Number.isFinite(q.price)||q.price<=0)return fail('INVALID_PRICE','Definitieve leveranciersprijs ontbreekt.');
        const rooms=q.roomTypes;
        if(!Array.isArray(rooms)||rooms.length!==1||!Array.isArray(rooms[0].rates)||rooms[0].rates.length!==1)return fail('INVALID_ROOM','Definitieve kamervoorwaarden zijn onvolledig.');
        const r=rooms[0].rates[0], approved=(s.supplier_mapping||s.supplier_content)?.offer, old=approved?.rates?.[0];
        if(!old||r.name!==old.name||r.boardType!==old.boardType||r.boardName!==old.boardName||r.adultCount!==old.adultCount||r.childCount!==old.childCount||r.remarks!==old.remarks||canonical(r.cancellationPolicies)!==canonical(old.cancellationPolicies))return {...fail('CONDITIONS_CHANGED','Kamer of annuleringsvoorwaarden zijn gewijzigd.'),differences:['name','boardType','boardName','adultCount','childCount','remarks','cancellationPolicies'].filter(k=>canonical(r[k])!==canonical(old?.[k])).map(k=>({field:k,current:r[k],approved:old?.[k]}))};
        const fees=r.retailRate?.taxesAndFees;
        if(!Array.isArray(fees)||fees.some(t=>typeof t.included!=='boolean'||t.currency!=='EUR'||typeof t.amount!=='number'||!Number.isFinite(t.amount)||t.amount<0))return fail('INVALID_FEES','Definitieve lokale kosten zijn onvolledig.');
        const local=fees.filter(t=>!t.included).map(t=>({description:t.description,amount:t.amount,currency:t.currency,pay_at_property:true}));
        const sorted=v=>canonical(v.slice().sort((x,y)=>canonical(x).localeCompare(canonical(y))));
        if(sorted(local)!==sorted(a.local_fees))return fail('LOCAL_FEES_CHANGED','Lokale kosten zijn gewijzigd sinds goedkeuring.');
        const cfg=s.pricing_config;
        if(!cfg||['processing_fee','stripe_fee_percentage','stripe_fee_fixed','min_margin_amount'].some(k=>typeof cfg[k]!=='number'||!Number.isFinite(cfg[k])||cfg[k]<0)||cfg.stripe_fee_percentage>=100)return fail('INVALID_CONFIG','Kostenconfiguratie ontbreekt.');
        const sale=Math.round(d.price*100),cost=Math.ceil(q.price*100-1e-8),processing=Math.ceil(Math.max(cfg.processing_fee,1.30)*100-1e-8),stripe=Math.ceil(sale*cfg.stripe_fee_percentage/100+cfg.stripe_fee_fixed*100-1e-8),margin=sale-cost-processing-stripe;
        if(margin<Math.ceil(cfg.min_margin_amount*100-1e-8))return fail('MARGIN_BLOCKED','Definitieve inkoopprijs past niet binnen de goedgekeurde verkoopprijs.');
        return {ready:true,can_pay:false,environment:'sandbox',deal_id:d.id,supplier_deal_id:s.id,approval_fingerprint:canonical({deal:d,supplier:s}),prebook_id:q.prebookId,checkin:$input.checkin,checkout:$input.checkout,guests:$input.guests,currency:'EUR',selling_price:sale/100,supplier_amount:cost/100,processing_reserve:processing/100,stripe_reserve:stripe/100,margin_after_reserve:margin/100,local_fees:local,cancellation_policies:r.cancellationPolicies,checked_at:Date.now(),message:'Sandboxprijs bevestigd; betaalroute nog niet aangesloten.'};
        """
      timeout = 5
    } as $result
  }

  response = $result
}

