const started=Date.now();
const results=await Promise.all([1,2].map(async n=>{const start=Date.now();const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:'evt_1UPL4EPz36j75L08XapWxLVN'})});return {n,start,end:Date.now(),http_status:r.status,result:await r.json()};}));
return {started,results};
"""
 timeout=30
